import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem88 preserva itens e distingue identidade de garantia ou kit semelhante',()=>{for(const [id,titulo] of [['KHQKsjwv2MzJGObyoZkd','Perfume Carolina Herrera Very Good Girl Glam Parfum 50ml feminino'],['KjczAN39YiZOmTgmzwIt','Cama Elástica Pula Pula Infantil Trampolim 1,4 Metros Atentu'],['kkADU0pbN4LUhcYR1HMH','Kit Principia para Rotina de Skincare Pele Sensível com Protetor Solar FPS 60']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.equal(x.titulo,titulo);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/diversão segura|certificação confirmada|hipoalergênico|fixação garantida/i);if(id==='kkADU0pbN4LUhcYR1HMH'){assert.match(x.comentario,/CM-01/);assert.match(x.comentario,/CH-01/);assert.match(x.comentario,/Não substituímos/);}}});
